-- Public catalog (replicated to workers) + the replication change log.
-- Timestamps: created_at / updated_at / sent_at are unix MILLISECONDS; changes.ts is unix SECONDS.
-- Ids are 20-char sortable strings generated by the repo layer (time prefix + random).

CREATE TABLE movies (
    id           TEXT PRIMARY KEY,
    title        TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 300),
    content_type TEXT NOT NULL DEFAULT 'movie' CHECK (content_type IN ('movie','series')),
    type         TEXT NOT NULL DEFAULT 'Movie',
    industry     TEXT NOT NULL DEFAULT '',
    year         INTEGER,
    rating       REAL CHECK (rating IS NULL OR (rating >= 0 AND rating <= 10)),
    poster_url   TEXT NOT NULL DEFAULT '',
    cover_url    TEXT NOT NULL DEFAULT '',
    cast_text    TEXT NOT NULL DEFAULT '',
    description  TEXT NOT NULL DEFAULT '',
    dubbed       INTEGER NOT NULL DEFAULT 0,
    is_private   INTEGER NOT NULL DEFAULT 0,
    is_upcoming  INTEGER NOT NULL DEFAULT 0,
    release_date TEXT NOT NULL DEFAULT '',
    release_ts   INTEGER,
    search_text  TEXT NOT NULL DEFAULT '',
    created_at   INTEGER NOT NULL,
    updated_at   INTEGER NOT NULL
);
CREATE INDEX movies_created ON movies(created_at, id);
CREATE INDEX movies_content_type ON movies(content_type);
CREATE INDEX movies_year ON movies(year);

CREATE TABLE seasons (
    id         TEXT PRIMARY KEY,
    movie_id   TEXT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    number     INTEGER NOT NULL,
    name       TEXT NOT NULL,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    UNIQUE (movie_id, name)
);
CREATE INDEX seasons_movie ON seasons(movie_id, number);

CREATE TABLE episodes (
    id         TEXT PRIMARY KEY,
    season_id  TEXT NOT NULL REFERENCES seasons(id) ON DELETE CASCADE,
    movie_id   TEXT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    number     INTEGER NOT NULL,
    name       TEXT NOT NULL,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
);
CREATE INDEX episodes_season ON episodes(season_id, number);
CREATE INDEX episodes_movie ON episodes(movie_id);

-- A link belongs to a movie (episode_id NULL) or to one of its episodes.
CREATE TABLE links (
    id         TEXT PRIMARY KEY,
    movie_id   TEXT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    episode_id TEXT REFERENCES episodes(id) ON DELETE CASCADE,
    kind       TEXT NOT NULL DEFAULT 'stream' CHECK (kind IN ('stream','download')),
    quality    TEXT NOT NULL DEFAULT '',
    label      TEXT NOT NULL DEFAULT '',
    url        TEXT NOT NULL,
    sort       INTEGER NOT NULL DEFAULT 0,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
);
CREATE INDEX links_owner ON links(movie_id, episode_id, kind, sort);
CREATE INDEX links_episode ON links(episode_id);

CREATE TABLE categories (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK (length(name) BETWEEN 1 AND 60),
    popular    INTEGER NOT NULL DEFAULT 0,
    sort       INTEGER NOT NULL DEFAULT 0,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
);

-- pos keeps the admin's genre order (the first genre is the "primary" one).
CREATE TABLE movie_categories (
    movie_id    TEXT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    category_id TEXT NOT NULL REFERENCES categories(id) ON DELETE CASCADE,
    pos         INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (movie_id, category_id)
) WITHOUT ROWID;
CREATE INDEX movie_categories_cat ON movie_categories(category_id);

CREATE TABLE movie_languages (
    movie_id TEXT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    language TEXT NOT NULL,
    pos      INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (movie_id, language)
) WITHOUT ROWID;

CREATE TABLE banners (
    id         TEXT PRIMARY KEY,
    image_url  TEXT NOT NULL,
    movie_id   TEXT REFERENCES movies(id) ON DELETE SET NULL,
    link_url   TEXT NOT NULL DEFAULT '',
    sort       INTEGER NOT NULL DEFAULT 0,
    active     INTEGER NOT NULL DEFAULT 1,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
);
CREATE INDEX banners_sort ON banners(sort, created_at);

CREATE TABLE social_links (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL,
    url        TEXT NOT NULL,
    icon       TEXT NOT NULL DEFAULT 'fas fa-link',
    sort       INTEGER NOT NULL DEFAULT 0,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
);

CREATE TABLE notifications (
    id         TEXT PRIMARY KEY,
    title      TEXT NOT NULL,
    message    TEXT NOT NULL,
    sent_at    INTEGER NOT NULL,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
);
CREATE INDEX notifications_sent ON notifications(sent_at);

-- Public site settings (appName, appLogo, themeMode, themeColor, themeInterval, pwdResetLimit).
CREATE TABLE settings (
    k          TEXT PRIMARY KEY,
    v          TEXT NOT NULL,
    updated_at INTEGER NOT NULL
) WITHOUT ROWID;

-- Replication log. Rows are written ONLY by the triggers below, in the same transaction as the data change.
-- Child tables (seasons, episodes, links, movie_categories, movie_languages) log an upsert of their MOVIE,
-- so a worker always receives a whole movie. The sync endpoint resolves each (tbl,row_id) by whether the row
-- still exists, so the order of log entries inside one transaction does not matter.
CREATE TABLE changes (
    seq    INTEGER PRIMARY KEY AUTOINCREMENT,
    tbl    TEXT NOT NULL,
    row_id TEXT NOT NULL,
    op     TEXT NOT NULL CHECK (op IN ('upsert','delete')),
    ts     INTEGER NOT NULL
);
CREATE INDEX changes_ts ON changes(ts);
CREATE INDEX changes_row ON changes(tbl, row_id);

-- movies
CREATE TRIGGER trg_movies_ai AFTER INSERT ON movies BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('movies', NEW.id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_movies_au AFTER UPDATE ON movies BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('movies', NEW.id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_movies_ad AFTER DELETE ON movies BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('movies', OLD.id, 'delete', CAST(strftime('%s','now') AS INTEGER)); END;

-- categories
CREATE TRIGGER trg_categories_ai AFTER INSERT ON categories BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('categories', NEW.id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_categories_au AFTER UPDATE ON categories BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('categories', NEW.id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_categories_ad AFTER DELETE ON categories BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('categories', OLD.id, 'delete', CAST(strftime('%s','now') AS INTEGER)); END;

-- banners
CREATE TRIGGER trg_banners_ai AFTER INSERT ON banners BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('banners', NEW.id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_banners_au AFTER UPDATE ON banners BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('banners', NEW.id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_banners_ad AFTER DELETE ON banners BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('banners', OLD.id, 'delete', CAST(strftime('%s','now') AS INTEGER)); END;

