CREATE TRIGGER trg_social_links_ai AFTER INSERT ON social_links BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('social_links', NEW.id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_social_links_au AFTER UPDATE ON social_links BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('social_links', NEW.id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_social_links_ad AFTER DELETE ON social_links BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('social_links', OLD.id, 'delete', CAST(strftime('%s','now') AS INTEGER)); END;

-- notifications
CREATE TRIGGER trg_notifications_ai AFTER INSERT ON notifications BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('notifications', NEW.id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_notifications_au AFTER UPDATE ON notifications BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('notifications', NEW.id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_notifications_ad AFTER DELETE ON notifications BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('notifications', OLD.id, 'delete', CAST(strftime('%s','now') AS INTEGER)); END;

-- settings
CREATE TRIGGER trg_settings_ai AFTER INSERT ON settings BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('settings', NEW.k, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_settings_au AFTER UPDATE ON settings BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('settings', NEW.k, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_settings_ad AFTER DELETE ON settings BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('settings', OLD.k, 'delete', CAST(strftime('%s','now') AS INTEGER)); END;

-- seasons -> upsert of the parent movie
CREATE TRIGGER trg_seasons_ai AFTER INSERT ON seasons BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('movies', NEW.movie_id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_seasons_au AFTER UPDATE ON seasons BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('movies', NEW.movie_id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_seasons_ad AFTER DELETE ON seasons WHEN EXISTS (SELECT 1 FROM movies WHERE id = OLD.movie_id) BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('movies', OLD.movie_id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;

-- episodes -> upsert of the parent movie
CREATE TRIGGER trg_episodes_ai AFTER INSERT ON episodes BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('movies', NEW.movie_id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_episodes_au AFTER UPDATE ON episodes BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('movies', NEW.movie_id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER trg_episodes_ad AFTER DELETE ON episodes WHEN EXISTS (SELECT 1 FROM movies WHERE id = OLD.movie_id) BEGIN INSERT INTO changes(tbl, row_id, op, ts) VALUES ('movies', OLD.movie_id, 'upsert', CAST(strftime('%s','now') AS INTEGER)); END;

